{{--
    Admin Sidebar Navigation Component

    A collapsible sidebar for the admin CMS panel.
    Uses Alpine.js for responsive toggle behavior.
--}}
<aside x-data="{ sidebarOpen: true }"
       :class="sidebarOpen ? 'w-64' : 'w-20'"
       class="bg-white border-r border-gray-200 min-h-screen transition-all duration-300 flex flex-col">
    {{-- Sidebar Header --}}
    <div class="flex items-center justify-between p-4 border-b border-gray-200">
        <a href="{{ url('/admin/dashboard') }}" class="flex items-center space-x-3">
            <div class="w-10 h-10 bg-primary-green rounded-lg flex items-center justify-center flex-shrink-0">
                <span class="text-white font-heading font-bold text-lg">L</span>
            </div>
            <span x-show="sidebarOpen" x-transition class="font-heading font-bold text-primary-green text-sm">
                Admin Panel
            </span>
        </a>
